import os,json,subprocess,urllib.request,datetime,hashlib
p=r'E:\WebAIBridge'
out={'at':datetime.datetime.now().isoformat(timespec='seconds'),'repo_exists':os.path.isdir(p)}
def git(*args):
 try:
  r=subprocess.run(['git.exe','-C',p,*args],capture_output=True,text=True,errors='replace',timeout=15)
  return {'code':r.returncode,'out':(r.stdout or '').strip()[:240],'error':(r.stderr or '').strip()[:160] if r.returncode else ''}
 except Exception as e:return {'error':type(e).__name__}
if out['repo_exists']:
 out['git_head']=git('rev-parse','HEAD')
 out['git_branch']=git('branch','--show-current')
 out['git_status_summary']={}
 try:
  r=subprocess.run(['git.exe','-C',p,'status','--porcelain=v1','-z','--untracked-files=all'],capture_output=True,timeout=15)
  z=[x for x in r.stdout.split(b'\0') if x]
  out['git_status_summary']={'code':r.returncode,'entry_count':len(z),'xy_codes':[x[:2].decode('ascii','replace') for x in z[:30]]}
 except Exception as e:out['git_status_summary']={'error':type(e).__name__}
 out['r44_object']=git('cat-file','-t','9a8898a70355bbae2d465ee49739030aa27e9f4e')
 out['r44_branch']=git('rev-parse','--verify','refs/heads/agent/bridge-r44-hotfix-r43-integration-20261007')
 out['cutover_present']=os.path.isfile(os.path.join(p,'app','r42-cutover.ps1'))
 out['rollback_present']=os.path.isfile(os.path.join(p,'app','r42-rollback.ps1'))
for endpoint in ['/api/health','/api/status']:
 try:
  with urllib.request.urlopen('http://127.0.0.1:17448'+endpoint,timeout=5) as f:
   d=json.load(f)
  if endpoint=='/api/health':out['health']={k:d.get(k) for k in ['state','ok','reasons','degraded','blockers','codeReload','assignmentQueue','browserProbe']}
  else:out['status']={k:d.get(k) for k in ['object','state','status','version']}
 except Exception as e:out[endpoint]={'error':type(e).__name__}
print(json.dumps(out,ensure_ascii=True,default=str))
